test('messages support replies, mentions, polls, edits, deletes, mute, archive, typing and seen-by',async()=>{
 const app=await fixture();try{
  const group=(await app.comm(app.alice,'threads','POST',{kind:'group',name:'Kitchen',members:[app.bobRecord.id]})).data;
  const first=(await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Who can cover Friday?'})).data;
  // Replies quote the original; mentions must be conversation members.
  const reply=(await app.comm(app.bob,'threads/'+group.id+'/messages','POST',{body:'@Alice I can',replyTo:first.id,mentions:[app.aliceRecord.id]})).data;
  assert.equal(reply.reply.id,first.id);assert.equal(reply.reply.authorName,'Alice');assert.equal(reply.reply.body,'Who can cover Friday?');
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages','POST',{body:'hi',mentions:[app.outsideRecord.id]})).status,400);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages','POST',{body:'x',replyTo:crypto.randomUUID()})).status,400);
  let view=(await app.comm(app.alice,'threads/'+group.id+'/messages')).data;assert.equal(view.messages.find(m=>m.id===reply.id).mentioned,true);assert.equal(view.messages.find(m=>m.id===reply.id).requestId,undefined);
  // Seen-by follows reads; typing is short-lived and only shown to others.
  await app.comm(app.bob,'threads/'+group.id+'/read','POST',{through:reply.sequence});
  assert.deepEqual((await app.comm(app.alice,'threads/'+group.id+'/messages')).data.seenBy,['Bob']);
  await app.comm(app.bob,'threads/'+group.id+'/typing','POST',{});
  assert.deepEqual((await app.comm(app.alice,'threads/'+group.id+'/messages')).data.typing,['Bob']);assert.deepEqual((await app.comm(app.bob,'threads/'+group.id+'/messages')).data.typing,[]);
  app.advance(7000);assert.deepEqual((await app.comm(app.alice,'threads/'+group.id+'/messages')).data.typing,[]);
  // Only the author edits; edits are visible through reaction deltas and keep history private.
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/messages/'+reply.id,'PUT',{body:'changed'})).status,403);
  const since=view.reactionRevision;const edited=(await app.comm(app.bob,'threads/'+group.id+'/messages/'+reply.id,'PUT',{body:'@Alice I can do Friday'})).data;
  assert.equal(edited.body,'@Alice I can do Friday');assert.ok(edited.editedAt);assert.equal(edited.history,undefined);
  const delta=(await app.comm(app.alice,'threads/'+group.id+'/messages?after='+reply.sequence+'&reactionsSince='+since)).data;assert.equal(delta.reactionUpdates.find(u=>u.id===reply.id).message.body,'@Alice I can do Friday');
  // Delete: Bob can't delete Alice's message; Alice (group owner) can delete Bob's.
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages/'+first.id,'DELETE')).status,403);
  const gone=(await app.comm(app.alice,'threads/'+group.id+'/messages/'+reply.id,'DELETE')).data;assert.equal(gone.deleted,true);assert.equal(gone.body,'');
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/messages')).data.messages.find(m=>m.id===first.id).canDelete,true);
  // Polls in group chats: one vote each unless multiple.
  const poll=(await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Team dinner?',poll:{question:'Which night?',options:['Monday','Tuesday']}})).data;
  assert.equal(poll.poll.options.length,2);const voted=(await app.comm(app.bob,'threads/'+group.id+'/messages/'+poll.id+'/poll','PUT',{optionIds:[poll.poll.options[1].id]})).data;assert.equal(voted.poll.options[1].count,1);assert.equal(voted.poll.options[1].voted,true);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages/'+poll.id+'/poll','PUT',{optionIds:poll.poll.options.map(o=>o.id)})).status,400);
  // Ending polls: leaders are reported, only the poll's author (or the group owner) can end it, and nobody can vote afterwards.
  assert.deepEqual(voted.poll.leading,[poll.poll.options[1].id]);assert.equal(voted.poll.voted,true);assert.equal(voted.poll.canClose,false);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages/'+poll.id+'/poll/close','POST',{})).status,403);
  const ended=(await app.comm(app.alice,'threads/'+group.id+'/messages/'+poll.id+'/poll/close','POST',{})).data;assert.equal(ended.poll.closed,true);assert.equal(ended.poll.canClose,false);assert.ok(ended.poll.closedAt);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages/'+poll.id+'/poll','PUT',{optionIds:[poll.poll.options[0].id]})).status,400);
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Late?',poll:{question:'Late?',options:['a','b'],closesAt:new Date(Date.parse('2026-10-15T11:00:00Z')).toISOString()}})).status,400);
  const timed=(await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Soon?',poll:{question:'Soon?',options:['a','b'],closesAt:'2026-10-15T13:00:00.000Z'}})).data;assert.equal(timed.poll.closed,false);assert.ok(timed.poll.closesAt);assert.equal(timed.poll.canClose,true);app.advance(2*3600000);assert.equal((await app.comm(app.bob,'threads/'+group.id+'/messages/'+timed.id+'/poll','PUT',{optionIds:[timed.poll.options[0].id]})).status,400);
  // Mute: only mentions count as unread; archive hides until a new message arrives.
  await app.comm(app.bob,'threads/'+group.id+'/read','POST',{through:poll.sequence});
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/settings','PUT',{muted:true})).data.muted,true);
  await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'General chatter'});
  assert.equal((await app.comm(app.bob,'unread')).data.unread,0);
  await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'@everyone meeting',mentionAll:true});
  assert.equal((await app.comm(app.bob,'unread')).data.unread,1);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/settings','PUT',{archived:true})).data.archived,true);
  app.advance(1000);await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Back again'});
  assert.equal((await app.comm(app.bob,'threads')).data.threads.find(t=>t.id===group.id).archived,false);
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/settings','PUT',{pinned:true})).status,400);
  // Direct messages: no @everyone or polls.
  const direct=(await app.comm(app.alice,'threads','POST',{kind:'direct',members:[app.bobRecord.id]})).data;
  assert.equal((await app.comm(app.alice,'threads/'+direct.id+'/messages','POST',{body:'hi',mentionAll:true})).status,400);
  assert.equal((await app.comm(app.alice,'threads/'+direct.id+'/messages','POST',{body:'hi',poll:{question:'q',options:['a','b']}})).status,400);
  assert.equal((await app.comm(app.outside,'threads/'+group.id+'/typing','POST',{})).status,404);
 }finally{await app.close();}
});

test('poll types: sign-up spots, event RSVP, ratings, one-try quizzes, short answers and numbers',async()=>{const app=await fixture();try{
  const group=(await app.comm(app.alice,'threads','POST',{kind:'group',name:'Shift team',members:[app.bobRecord.id]})).data;const make=async poll=>app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:poll.question,poll});const vote=(who,m,body)=>app.comm(who,'threads/'+group.id+'/messages/'+m.id+'/poll','PUT',body);
  assert.equal((await make({kind:'nonsense',question:'x',options:['a','b']})).status,400);
  // Sign-up: spots fill up; a full slot rejects newcomers but keeps the people already in it.
  const signup=(await make({kind:'signup',question:'Cover Saturday',options:[{text:'Open',spots:1},{text:'Close'}]})).data;assert.equal(signup.poll.kind,'signup');assert.equal(signup.poll.options[0].spots,1);
  assert.equal((await vote(app.alice,signup,{optionIds:[signup.poll.options[0].id]})).data.poll.options[0].full,true);
  assert.equal((await vote(app.bob,signup,{optionIds:[signup.poll.options[0].id]})).status,400);
  assert.equal((await vote(app.alice,signup,{optionIds:[signup.poll.options[0].id]})).status,200);
  assert.equal((await make({kind:'signup',question:'x',options:[{text:'a',spots:0}]})).status,400);
  // Event RSVP: fixed answers and an event time.
  assert.equal((await make({kind:'rsvp',question:'Team dinner',options:[]})).status,400);
  const rsvp=(await make({kind:'rsvp',question:'Team dinner',event:{at:'2026-10-20T08:00:00.000Z',place:'Back room'}})).data;assert.deepEqual(rsvp.poll.options.map(o=>o.text),['Going','Maybe','Can’t go']);assert.equal(rsvp.poll.event.place,'Back room');
  // Rating: 1–5 or 1–10 with an average.
  assert.equal((await make({kind:'rating',question:'x',scale:7})).status,400);
  const rating=(await make({kind:'rating',question:'How busy was lunch?',scale:5})).data;await vote(app.alice,rating,{optionIds:[rating.poll.options[3].id]});const rated=(await vote(app.bob,rating,{optionIds:[rating.poll.options[1].id]})).data;assert.equal(rated.poll.average,3);assert.equal(rated.poll.scale,5);
  // Quiz: the answer stays hidden until you answer; one try only.
  assert.equal((await make({kind:'quiz',question:'Cool room temperature?',options:['5°C or below','10°C']})).status,400);
  const quiz=(await make({kind:'quiz',question:'Cool room temperature?',options:['5°C or below','10°C'],correct:0})).data;assert.equal(quiz.poll.revealed,true);
  const unseen=(await app.comm(app.bob,'threads/'+group.id+'/messages')).data.messages.find(m=>m.id===quiz.id).poll;assert.equal(unseen.revealed,undefined);assert.ok(unseen.options.every(o=>o.correct===undefined));
  const answered=(await vote(app.bob,quiz,{optionIds:[quiz.poll.options[1].id]})).data.poll;assert.equal(answered.revealed,true);assert.equal(answered.correctCount,0);assert.equal(answered.options[0].correct,true);
  assert.equal((await vote(app.bob,quiz,{optionIds:[quiz.poll.options[0].id]})).status,400);
  // Short answer and number: typed replies listed with names; numbers validate bounds and average.
  const reply=(await make({kind:'question',question:'Any ideas for the special?'})).data;assert.equal((await vote(app.bob,reply,{text:'  '})).status,400);const replied=(await vote(app.bob,reply,{text:'Lamb wrap'})).data.poll;assert.equal(replied.total,1);assert.equal(replied.answers[0].text,'Lamb wrap');assert.equal(replied.mine,'Lamb wrap');assert.equal((await vote(app.bob,reply,{clear:true})).data.poll.total,0);
  const number=(await make({kind:'number',question:'Trays for Friday?',min:0,max:50,unit:'trays'})).data;assert.equal((await vote(app.bob,number,{value:60})).status,400);await vote(app.bob,number,{value:10});const counted=(await vote(app.alice,number,{value:15})).data.poll;assert.equal(counted.average,12.5);assert.equal(counted.lowest,10);assert.equal(counted.highest,15);assert.equal(counted.unit,'trays');
  assert.equal((await make({kind:'number',question:'x',min:5,max:5})).status,400);
  // Ending works for every type.
  await app.comm(app.alice,'threads/'+group.id+'/messages/'+reply.id+'/poll/close','POST',{});assert.equal((await vote(app.bob,reply,{text:'late'})).status,400);
  // Posts take the same types.
  const event=(await app.post({title:'Staff party',poll:{kind:'rsvp',question:'Staff party',event:{at:'2026-12-20T08:00:00.000Z'}}})).data;assert.equal(event.poll.kind,'rsvp');
 }finally{await app.close();}});
test('chats can be customised: colours, backgrounds, quick emoji, nicknames and group details',async()=>{const app=await fixture();try{
  const group=(await app.comm(app.alice,'threads','POST',{kind:'group',name:'Floor team',members:[app.bobRecord.id]})).data;assert.equal(group.custom.colour,'default');assert.equal(group.canCustomise,true);
  // Only the owner (or a Comms manager) customises a group; members see the shared look.
  assert.equal((await app.comm(app.bob,'threads/'+group.id+'/customise','PUT',{colour:'teal'})).status,403);
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{colour:'neon'})).status,400);
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{emoji:'abc'})).status,400);
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{nicknames:{[app.outsideRecord.id]:'Nope'}})).status,400);
  const saved=(await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{revision:0,colour:'teal',background:'dots',emoji:'🔥',nicknames:{[app.bobRecord.id]:'Bobby'},name:'Floor crew',description:'Front of house chat'})).data;
  assert.equal(saved.name,'Floor crew');assert.deepEqual([saved.custom.colour,saved.custom.background,saved.custom.emoji,saved.custom.nicknames[app.bobRecord.id],saved.custom.description],['teal','dots','🔥','Bobby','Front of house chat']);
  const bobView=(await app.comm(app.bob,'threads')).data.threads.find(t=>t.id===group.id);assert.equal(bobView.custom.colour,'teal');assert.equal(bobView.canCustomise,false);
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{revision:0,colour:'red'})).status,409);
  // Group photos: uploaded by the owner and readable by members only.
  const photo=(await app.comm(app.alice,'media','POST',{name:'team.png',mime:'image/png',data:Buffer.from('89504e470d0a1a0a0000000d4948445200000001000000010806000000','hex').toString('base64')}));
  assert.equal(photo.status,201,JSON.stringify(photo.data));if(photo.status===201){const withPhoto=(await app.comm(app.alice,'threads/'+group.id+'/customise','PUT',{photoId:photo.data.id})).data;assert.ok(withPhoto.custom.photoUrl);assert.equal((await app.request(app.bob,withPhoto.custom.photoUrl)).status,200);assert.equal((await app.request(app.outside,withPhoto.custom.photoUrl)).status,404);}
  // Direct chats: each person keeps their own look; group-only fields are refused.
  const direct=(await app.comm(app.alice,'threads','POST',{kind:'direct',members:[app.bobRecord.id]})).data;
  assert.equal((await app.comm(app.alice,'threads/'+direct.id+'/customise','PUT',{name:'x'})).status,400);
  await app.comm(app.alice,'threads/'+direct.id+'/customise','PUT',{colour:'pink',nicknames:{[app.bobRecord.id]:'B'}});
  assert.equal((await app.comm(app.alice,'threads')).data.threads.find(t=>t.id===direct.id).custom.colour,'pink');
  assert.equal((await app.comm(app.bob,'threads')).data.threads.find(t=>t.id===direct.id).custom.colour,'default');
 }finally{await app.close();}});

test('chat looks support themes, custom colours, bubble styles, text, layout and several quick reactions',async()=>{const app=await fixture();try{
  const direct=(await app.comm(app.alice,'threads','POST',{kind:'direct',members:[app.bobRecord.id]})).data,url='threads/'+direct.id+'/customise';
  // Defaults are reported for every option.
  const fresh=(await app.comm(app.alice,'threads')).data.threads.find(t=>t.id===direct.id).custom;
  assert.deepEqual([fresh.bubble,fresh.sent,fresh.received,fresh.textSize,fresh.font,fresh.density,fresh.layout,fresh.times,fresh.names,fresh.emojis.join('')],['rounded','solid','grey','normal','default','normal','split','always','show','👍']);
  // Validation: unknown values, custom colour without a hex, too many emoji and bad wallpaper emoji are refused.
  for(const bad of [{bubble:'blob'},{font:'Comic'},{textSize:'huge'},{colour:'custom'},{colour:'custom',customColour:'red'},{emojis:['👍','🔥','🎉','❤️']},{emojis:[]},{emojis:['ok']},{wallpaperEmoji:'abc'},{names:'nobody'}])assert.equal((await app.comm(app.alice,url,'PUT',bad)).status,400,JSON.stringify(bad));
  const saved=(await app.comm(app.alice,url,'PUT',{colour:'custom',customColour:'#AA33CC',background:'emoji',wallpaperEmoji:'🍕',bubble:'pill',sent:'gradient',received:'white',textSize:'large',font:'serif',density:'roomy',layout:'left',times:'hover',names:'others',emojis:['🔥','👍','🔥','🎉']})).data;
  assert.ok(saved.custom,JSON.stringify(saved));assert.equal(saved.custom.customColour,'#aa33cc');assert.equal(saved.custom.background,'emoji');assert.equal(saved.custom.wallpaperEmoji,'🍕');
  assert.deepEqual(saved.custom.emojis,['🔥','👍','🎉']);assert.equal(saved.custom.emoji,'🔥');
  assert.deepEqual([saved.custom.bubble,saved.custom.sent,saved.custom.received,saved.custom.textSize,saved.custom.font,saved.custom.density,saved.custom.layout,saved.custom.times,saved.custom.names],['pill','gradient','white','large','serif','roomy','left','hover','others']);
  // Older writers that send only some fields keep the rest; a single emoji moves to the front of the list.
  const older=(await app.comm(app.alice,url,'PUT',{colour:'teal',emoji:'🎉'})).data.custom;
  assert.equal(older.colour,'teal');assert.equal(older.customColour,undefined);assert.equal(older.bubble,'pill');assert.deepEqual(older.emojis,['🎉','🔥','👍']);
  // Bob's own look for the same direct chat is untouched.
  assert.equal((await app.comm(app.bob,'threads')).data.threads.find(t=>t.id===direct.id).custom.bubble,'rounded');
 }finally{await app.close();}});
test('posts support scheduling, polls, comments, read reminders and on-shift audiences',async()=>{
 const app=await fixture();try{
  // Scheduled posts stay with the author until their time.
  const later=new Date(Date.parse('2026-10-15T12:00:00Z')+3600000).toISOString();
  const scheduled=(await app.post({title:'Monday specials',publishAt:later})).data;assert.equal(scheduled.scheduled,true);
  assert.ok(!(await app.comm(app.alice,'posts')).data.posts.some(p=>p.id===scheduled.id));assert.ok((await app.comm(app.office,'posts')).data.posts.some(p=>p.id===scheduled.id));
  assert.equal((await app.post({title:'Past',publishAt:'2026-01-01T00:00:00Z'})).status,400);
  app.advance(3600001);assert.ok((await app.comm(app.alice,'posts')).data.posts.some(p=>p.id===scheduled.id));
  // Polls on posts; options are fixed once people vote.
  const pollPost=(await app.post({title:'Meeting day',poll:{question:'Which day?',options:['Mon','Wed','Fri'],multiple:true}})).data;
  const ids=pollPost.poll.options.map(o=>o.id);const voted=(await app.comm(app.alice,'posts/'+pollPost.id+'/poll','PUT',{optionIds:[ids[0],ids[2]]})).data;assert.deepEqual(voted.poll.options.map(o=>o.count),[1,0,1]);assert.equal(voted.poll.total,1);
  assert.equal((await app.comm(app.office,'posts/'+pollPost.id,'PUT',{title:'Meeting day',body:'x',requireRead:false,revision:pollPost.revision,poll:{question:'Other',options:['A','B']}})).status,400);
  assert.equal(voted.poll.canClose,false);assert.equal((await app.comm(app.alice,'posts/'+pollPost.id+'/poll/close','POST',{})).status,403);
  const endedPost=(await app.comm(app.office,'posts/'+pollPost.id+'/poll/close','POST',{})).data;assert.equal(endedPost.poll.closed,true);
  assert.equal((await app.comm(app.alice,'posts/'+pollPost.id+'/poll','PUT',{optionIds:[ids[1]]})).status,400);
  // Comments: anyone who can chat; authors, the post author and managers remove them.
  const commented=(await app.comm(app.alice,'posts/'+pollPost.id+'/comments','POST',{body:'Wednesday suits me'})).data;assert.equal(commented.commentCount,1);const commentId=commented.comments[0].id;
  assert.equal((await app.comm(app.bob,'posts/'+pollPost.id+'/comments/'+commentId,'DELETE')).status,403);
  assert.equal((await app.comm(app.office,'posts/'+pollPost.id+'/comments/'+commentId,'DELETE')).data.commentCount,0);
  assert.equal((await app.comm(app.outside,'posts/'+pollPost.id+'/comments','POST',{body:'hi'})).status,404);
  // Reminders for required posts: author only, unread readers are re-notified, once an hour.
  const required=(await app.post({title:'New safety rule',requireRead:true})).data;
  await app.comm(app.alice,'posts/'+required.id+'/snooze','POST',{revision:required.revision});
  assert.equal((await app.comm(app.alice,'posts/'+required.id+'/remind','POST',{revision:required.revision})).status,403);
  const reminded=(await app.comm(app.office,'posts/'+required.id+'/remind','POST',{revision:required.revision})).data;assert.ok(reminded.reminded>=2);
  assert.ok((await app.comm(app.alice,'required')).data.due.some(p=>p.id===required.id),'a reminder clears the snooze');
  assert.equal((await app.comm(app.office,'posts/'+required.id+'/remind','POST',{revision:required.revision})).status,400);
  for(const actor of [app.alice,app.bob])await app.comm(actor,'posts/'+required.id+'/read','POST',{revision:required.revision});
  // On-shift audience: frozen to people on a published shift right now at the author's location.
  assert.equal((await app.post({title:'Urgent',audience:{kind:'on-shift'}})).status,400);
  const locationId=app.office.session.locationId,companyId=app.office.session.companyId;
  await fs.writeFile(path.join(app.dir,'rostering.json'),JSON.stringify({weeks:[{locationId,companyId,weekStart:'2026-10-12',publishedAt:'2026-10-10T00:00:00Z',published:[{userId:app.bobRecord.id,date:'2026-10-15',start:'22:00',end:'02:00'}]}],availability:[],rates:[],rateRevisions:[],budgets:[],entries:[]}));
  const urgent=(await app.post({title:'Urgent: freezer down',audience:{kind:'on-shift'}})).data;assert.equal(urgent.audience.count,1);
  assert.ok((await app.comm(app.bob,'posts')).data.posts.some(p=>p.id===urgent.id));assert.ok(!(await app.comm(app.alice,'posts')).data.posts.some(p=>p.id===urgent.id));
 }finally{await app.close();}
});

test('every active location has an automatic store group that follows location access',async()=>{
 const app=await fixture();try{
  const groups=(await app.comm(app.alice,'threads')).data.threads.filter(t=>t.kind==='location');assert.equal(groups.length,1);const group=groups[0];
  assert.ok(group.members.some(m=>m.id===app.bobRecord.id));assert.ok(!group.members.some(m=>m.id===app.outsideRecord.id));
  assert.ok(!(await app.comm(app.outside,'threads')).data.threads.some(t=>t.id===group.id));
  assert.equal((await app.comm(app.outside,'threads/'+group.id+'/messages')).status,404);
  // Reading never creates it; the first message saves it and others see it.
  assert.equal((await app.comm(app.alice,'threads/'+group.id+'/messages')).data.messages.length,0);
  const sent=(await app.comm(app.alice,'threads/'+group.id+'/messages','POST',{body:'Delivery is late today',mentionAll:true})).data;assert.equal(sent.body,'Delivery is late today');
  assert.equal((await app.comm(app.bob,'threads')).data.threads.find(t=>t.id===group.id).unread,1);
  assert.ok((await app.comm(app.bob,'threads/'+group.id+'/messages')).data.messages.some(m=>m.id===sent.id&&m.mentioned));
  assert.equal((await app.comm(app.outside,'threads/'+group.id+'/messages','POST',{body:'hi'})).status,404);
 }finally{await app.close();}
});
